mapper.select:
SELECT c.*
FROM agent_conversation c
WHERE c.last_user_message_time <= #{asOf}

    AND c.agent_uid = #{agentUid}


    AND (
        c.pinned < #{beforePinned}
        OR (c.pinned = #{beforePinned} AND c.last_user_message_time < #{beforeLastUserMessageTime})
        OR (c.pinned = #{beforePinned} AND c.last_user_message_time = #{beforeLastUserMessageTime} AND c.id < #{beforeId})
    )

ORDER BY c.pinned DESC, c.last_user_message_time DESC, c.id DESC
LIMIT #{limit}
